import gdb
class T(gdb.Command):
    def __init__(self): super().__init__("tr", gdb.COMMAND_USER)
    def invoke(self, arg, tty):
        path=arg
        gdb.execute("break aom_decode_frame_from_obus")
        gdb.execute("run %s"%path)
        gdb.execute("break aom_rb_read_bit")
        gdb.execute("break aom_rb_read_literal")
        seen_seq=False
        for i in range(800):
            gdb.execute("continue")
            try: f2=gdb.selected_frame()
            except gdb.error: break
            fname=f2.name()
            if fname not in ("aom_rb_read_bit","aom_rb_read_literal"):
                print("STOP->",fname); break
            caller=f2.older(); cname=caller.name(); line=caller.find_sal().line
            rbb=f2.read_var("rb")
            n=1 if fname=="aom_rb_read_bit" else int(f2.read_var("bits"))
            for _ in range(8000):
                gdb.execute("stepi", to_string=True)
                if gdb.selected_frame().name()==cname: break
            rbb2=caller.read_var("rb"); off2=int(rbb2["bit_offset"]); buf=int(rbb2["bit_buffer"])
            v=0
            for k in range(n):
                bitpos=off2-n+k
                byte=(buf >> ((bitpos//8)*8)) & 0xff
                v=(v<<1)|((byte >> (7-(bitpos%8)))&1)
            print("off=%d n=%d -> %d  (%s:%d)"%(off2-n,n,v,cname,line))
            if cname=="read_uncompressed_header" and line>4720: 
                pass
T()

