import gdb
# break at av1_read_sequence_header entry, then finish reads
state={"armed":False,"depth":0}
def onstop(ev):
    pass
class T(gdb.Command):
    def __init__(self): super().__init__("tr",gdb.COMMAND_USER)
    def invoke(self,arg,tty):
        gdb.execute("set pagination off")
        gdb.execute("break av1_read_sequence_header")
        gdb.execute("break aom_internal_error")
        gdb.execute("break aom_rb_read_bit")
        gdb.execute("break aom_rb_read_literal")
        gdb.execute("run %s"%arg)
        # We want only reads whose caller chain includes read_sequence_header or color_config etc.
        for i in range(400):
            try: f=gdb.selected_frame()
            except gdb.error: print("EXITED"); break
            nm=f.name()
            if nm=="aom_internal_error":
                print("INTERNAL_ERROR"); 
                try: gdb.execute("p (char*)$rdx")
                except: pass
                gdb.execute("continue"); continue
            if nm in ("aom_rb_read_bit","aom_rb_read_literal"):
                caller=f.older()
                cn=caller.name() if caller else "?"
                try: line=caller.find_sal().line
                except: line=-1
                try:
                    off0=int(f.read_var("rb")["bit_offset"])
                except:
                    off0=-1
                n=1 if nm=="aom_rb_read_bit" else int(f.read_var("bits"))
                # finish
                gdb.execute("finish",to_string=True)
                try:
                    cf=gdb.selected_frame()
                    off1=int(cf.read_var("rb")["bit_offset"])
                except: off1=-1
                print("off=%d n=%d caller=%s:%d"%(off0,n,cn,line))
                gdb.execute("continue"); continue
            # at av1_read_sequence_header entry
            print("ENTER:",nm)
            gdb.execute("continue")
        gdb.execute("quit")
T()
EOF
