            except gdb.error: print("EXITED"); break
            nm=f.name()
            if nm=="aom_internal_error":
                print("INTERNAL_ERROR"); 
                try: gdb.execute("p (char*)$rdx")
                except: pass
                gdb.execute("continue"); continue
            if nm in ("aom_rb_read_bit","aom_rb_read_literal"):
                caller=f.older()
                cn=caller.name() if caller else "?"
                try: line=caller.find_sal().line
                except: line=-1
                try:
                    off0=int(f.read_var("rb")["bit_offset"])
                except:
                    off0=-1
                n=1 if nm=="aom_rb_read_bit" else int(f.read_var("bits"))
                # finish
                gdb.execute("finish",to_string=True)
                try:
                    cf=gdb.selected_frame()
                    off1=int(cf.read_var("rb")["bit_offset"])
                except: off1=-1
                print("off=%d n=%d caller=%s:%d"%(off0,n,cn,line))
                gdb.execute("continue"); continue
